const express = require('express');
const router = express.Router();

// メモリ上で TODO を管理する（サーバー再起動でリセットされる）
let todos = [];
let nextId = 1;

// GET /todos - TODO 一覧を取得
router.get('/', (req, res) => {
  res.json(todos);
});

// POST /todos - 新しい TODO を作成
router.post('/', (req, res) => {
  const { title } = req.body;

  // タイトルが空の場合はエラー
  if (!title || title.trim() === '') {
    return res.status(400).json({ error: 'タイトルは必須です' });
  }

  const todo = {
    id: nextId++,
    title: title.trim(),
    completed: false,
    createdAt: new Date().toISOString(),
  };

  todos.push(todo);
  res.status(201).json(todo);
});

// PATCH /todos/:id - TODO の完了状態を更新
router.patch('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  const todo = todos.find((t) => t.id === id);

  if (!todo) {
    return res.status(404).json({ error: '指定された TODO が見つかりません' });
  }

  // completed フィールドのみ更新を許可
  if (typeof req.body.completed === 'boolean') {
    todo.completed = req.body.completed;
  }

  res.json(todo);
});

// DELETE /todos/:id - TODO を削除
router.delete('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  const index = todos.findIndex((t) => t.id === id);

  if (index === -1) {
    return res.status(404).json({ error: '指定された TODO が見つかりません' });
  }

  todos.splice(index, 1);
  res.status(204).send();
});

module.exports = router;

